export declare const neoBrutalismTheme = "/* \u65B0\u7C97\u91CE\u4E3B\u4E49\u98CE\u683C */\n#wemd {\n    padding: 5px 22px;\n    max-width: 677px;\n    margin: 0 auto;\n    font-family: -apple-system, \"Helvetica Neue\", \"PingFang SC\", \"Microsoft YaHei\", sans-serif;\n    color: #000;\n    /* \u7EAF\u9ED1\u6587\u5B57\uFF0C\u6781\u81F4\u5BF9\u6BD4 */\n    /* \u900F\u660E\u80CC\u666F\uFF0C\u517C\u5BB9\u5FAE\u4FE1\u6DF1\u8272\u6A21\u5F0F */\n    background-color: transparent;\n    word-break: break-word;\n}\n\n/* \u6BB5\u843D - \u9AD8\u5BF9\u6BD4\u5EA6 */\n#wemd p {\n    margin-top: 24px;\n    margin-bottom: 24px;\n    line-height: 1.8;\n    letter-spacing: 0.5px;\n    text-align: justify;\n    color: #111;\n    font-size: 16px;\n    font-weight: 400;\n}\n\n/* \n * \u4E00\u7EA7\u6807\u9898 - \u50CF\u4E00\u4E2A\u9192\u76EE\u7684\u6807\u7B7E\u76D2\u5B50\n * \u8BBE\u8BA1\uFF1A\u7C97\u8FB9\u6846 + \u8367\u5149\u9EC4\u80CC\u666F + \u786C\u9634\u5F71\n */\n#wemd h1 {\n    margin-top: 60px;\n    margin-bottom: 50px;\n    text-align: center;\n}\n\n#wemd h1 .content {\n    display: inline-block;\n    font-size: 24px;\n    font-weight: 900;\n    color: #000;\n    background-color: #CCFF00;\n    /* \u8367\u5149\u9EC4\u9AD8\u4EAE */\n    border: 3px solid #000;\n    /* \u7C97\u9ED1\u8FB9\u6846 */\n    padding: 12px 20px;\n    /* \u5173\u952E\uFF1A\u9ED1\u8272\u786C\u9634\u5F71 */\n    box-shadow: 6px 6px 0px #000;\n    line-height: 1.3;\n}\n\n#wemd h1 .prefix,\n#wemd h1 .suffix {\n    display: none;\n}\n\n/* \n * \u4E8C\u7EA7\u6807\u9898 - \u4E0B\u5212\u7EBF\u9AD8\u4EAE\n * \u8BBE\u8BA1\uFF1A\u6587\u5B57\u4E0B\u65B9\u7684\u539A\u5B9E\u8272\u5757\n */\n#wemd h2 {\n    margin-top: 60px;\n    margin-bottom: 30px;\n    text-align: left;\n    border-bottom: 3px solid #000;\n    /* \u901A\u680F\u7C97\u9ED1\u7EBF */\n    padding-bottom: 10px;\n}\n\n#wemd h2 .content {\n    display: inline-block;\n    font-size: 20px;\n    font-weight: 800;\n    color: #fff;\n    background-color: #6A00FF;\n    /* \u7535\u5149\u7D2B\u80CC\u666F */\n    padding: 8px 16px;\n    border: 2px solid #000;\n    /* \u5DE6\u4E0A\u504F\u79FB\u7684\u9634\u5F71\u6548\u679C */\n    box-shadow: 4px -4px 0px #000;\n    line-height: 1.2;\n}\n\n#wemd h2 .prefix,\n#wemd h2 .suffix {\n    display: none;\n}\n\n/* \n * \u4E09\u7EA7\u6807\u9898 - \u51E0\u4F55\u5F15\u5BFC\n */\n#wemd h3 {\n    margin-top: 40px;\n    margin-bottom: 20px;\n}\n\n#wemd h3 .content {\n    display: inline-block;\n    font-size: 18px;\n    font-weight: 800;\n    color: #000;\n    padding-left: 12px;\n    border-left: 8px solid #CCFF00;\n    /* \u6781\u7C97\u7684\u9EC4\u7EBF */\n    line-height: 1.2;\n}\n\n#wemd h3 .prefix,\n#wemd h3 .suffix {\n    display: none;\n}\n\n/* \n * \u56DB\u7EA7\u6807\u9898 - \u53CD\u8272\u9ED1\u76D2\n */\n#wemd h4 {\n    margin-top: 30px;\n    margin-bottom: 15px;\n    text-align: left;\n}\n\n#wemd h4 .content {\n    display: inline-block;\n    font-size: 16px;\n    font-weight: 700;\n    color: #fff;\n    background-color: #000;\n    /* \u7EAF\u9ED1\u80CC\u666F */\n    padding: 6px 12px;\n    border-radius: 0;\n    /* \u76F4\u89D2 */\n    line-height: 1.4;\n}\n\n#wemd h4 .prefix,\n#wemd h4 .suffix {\n    display: none;\n}\n\n/* \n * \u5217\u8868 - \u5F3A\u70C8\u7684\u51E0\u4F55\u611F\n * \u5FC5\u987B\u4F7F\u7528\u6B63\u65B9\u5F62\n */\n#wemd ul {\n    list-style-type: square;\n    padding-left: 20px;\n    margin: 20px 0;\n    color: #6A00FF;\n    /* \u7D2B\u8272\u65B9\u5757 */\n}\n\n#wemd ul li {\n    margin-bottom: 12px;\n    line-height: 1.75;\n}\n\n#wemd li section {\n    color: #000;\n    font-size: 16px;\n    font-weight: 500;\n}\n\n/* \u6709\u5E8F\u5217\u8868 - \u7C97\u9ED1\u4F53\u6570\u5B57 */\n#wemd ol {\n    list-style-type: decimal;\n    padding-left: 20px;\n    margin: 20px 0;\n    color: #000;\n    font-weight: 900;\n    /* \u6700\u7C97\u5B57\u4F53 */\n}\n\n#wemd ol li {\n    margin-bottom: 12px;\n    line-height: 1.75;\n    border-bottom: 1px solid #eee;\n    /* \u589E\u52A0\u5206\u5272\u7EBF */\n    padding-bottom: 8px;\n}\n\n#wemd ol li section {\n    color: #222;\n    font-weight: normal;\n    font-size: 16px;\n    padding-left: 5px;\n}\n\n#wemd ul ul {\n    list-style-type: circle;\n    color: #CCFF00;\n    margin-top: 10px;\n}\n\n#wemd ol ol {\n    list-style-type: upper-alpha;\n    color: #6A00FF;\n    font-weight: 900;\n}\n\n/* \n * \u5F15\u7528 - \u89C6\u7A97\u98CE\u683C (Window Style)\n * \u8FD9\u662F\u4E00\u4E2A\u5E26\u7C97\u8FB9\u6846\u548C\u786C\u9634\u5F71\u7684\u76D2\u5B50\n */\n#wemd .multiquote-1,\n#wemd .multiquote-2,\n#wemd .multiquote-3 {\n    margin: 40px 0;\n    padding: 24px;\n    background-color: #f4f4f4;\n    /* \u6D45\u7070\u80CC\u666F */\n    border: 2px solid #000;\n    /* \u7C97\u9ED1\u8FB9\u6846 */\n    /* \u7ECF\u5178\u7684\u6CE2\u666E\u98CE\u786C\u9634\u5F71 */\n    box-shadow: 6px 6px 0px #6A00FF;\n    overflow: visible !important;\n}\n\n#wemd .multiquote-1 p,\n#wemd .multiquote-2 p,\n#wemd .multiquote-3 p {\n    margin: 0;\n    color: #000;\n    font-size: 15px;\n    line-height: 1.8;\n    font-weight: 500;\n}\n\n#wemd .multiquote-2 {\n    margin: 38px 0;\n    padding: 22px;\n    background: #fff;\n    border: 2px solid #000;\n    box-shadow: 5px 5px 0px #CCFF00;\n}\n\n#wemd .multiquote-3 {\n    margin: 36px 0;\n    padding: 20px;\n    background: #fafafa;\n    border: 2px solid #000;\n    box-shadow: 4px 4px 0px #FF6B9D;\n}\n\n/* \u94FE\u63A5 - \u8367\u5149\u7B14\u6D82\u62B9\u6548\u679C */\n#wemd a {\n    color: #000;\n    /* \u94FE\u63A5\u6587\u5B57\u9ED1\u8272 */\n    text-decoration: none;\n    border-bottom: 2px solid #000;\n    background: linear-gradient(180deg, transparent 60%, #CCFF00 0);\n    /* \u4E0B\u534A\u90E8\u5206\u9EC4\u8272\u9AD8\u4EAE */\n    font-weight: 700;\n    padding: 0 2px;\n    transition: all 0.2s;\n}\n\n/* \n * \u52A0\u7C97 - \u6545\u969C\u98CE\u6548\u679C\n * \u7D2B\u8272\u80CC\u666F + \u767D\u5B57\n */\n#wemd strong {\n    color: #fff;\n    background-color: #6A00FF;\n    font-weight: 700;\n    padding: 2px 6px;\n    margin: 0 2px;\n    border: 1px solid #000;\n    /* \u52A0\u4E2A\u7EC6\u9ED1\u8FB9 */\n}\n\n/* \u659C\u4F53 */\n#wemd em {\n    color: #6A00FF;\n    font-style: italic;\n    font-weight: bold;\n}\n\n#wemd em strong {\n    color: #fff;\n}\n\n/* \u9AD8\u4EAE - \u8367\u5149\u9EC4\u5757 */\n#wemd mark {\n    background: #CCFF00;\n    color: #000;\n    padding: 2px 6px;\n    border: 2px solid #000;\n    font-weight: bold;\n}\n\n/* \u5220\u9664\u7EBF - \u7C97\u7EBF */\n#wemd del {\n    text-decoration: line-through;\n    text-decoration-thickness: 3px;\n    text-decoration-color: #FF6B9D;\n    color: #666;\n}\n\n/* \u5206\u9694\u7EBF - \u7C97\u9ED1\u6761 */\n#wemd hr {\n    margin: 60px auto;\n    border: 0;\n    height: 4px;\n    background: #000;\n    width: 100%;\n}\n\n/* \n * \u56FE\u7247 - \u62CD\u7ACB\u5F97\u6548\u679C\n * \u7C97\u6846 + \u786C\u9634\u5F71\n */\n#wemd img {\n    display: block;\n    margin: 40px auto;\n    width: 100%;\n    border: 2px solid #000;\n    box-shadow: 8px 8px 0px #000;\n    /* \u7EAF\u9ED1\u786C\u9634\u5F71 */\n    padding: 0;\n    background: #fff;\n}\n\n/* \u9488\u5BF9\u56FE\u7247\u4E0B\u65B9\u7684\u6CE8\u91CA\u6587\u5B57 */\n#wemd figcaption {\n    margin-top: 12px;\n    text-align: center;\n    color: #000;\n    font-size: 14px;\n    font-weight: bold;\n    background: #CCFF00;\n    padding: 4px 10px;\n    border: 2px solid #000;\n    display: inline-block;\n    box-shadow: 3px 3px 0 #000;\n}\n\n/* \u884C\u5185\u4EE3\u7801 - \u590D\u53E4\u7EC8\u7AEF\u98CE */\n#wemd p code,\n#wemd li code,\n#wemd td code,\n#wemd th code {\n    color: #000;\n    background: #fff;\n    border: 1px solid #000;\n    padding: 2px 6px;\n    margin: 0 4px;\n    font-size: 14px;\n    font-family: \"Menlo\", monospace;\n    font-weight: bold;\n    box-shadow: 2px 2px 0 #ccc;\n}\n\n/* \u4EE3\u7801\u5757 - \u7EAF\u9ED1\u786C\u6838\u6A21\u5F0F */\n/* \u4EE3\u7801\u5757 - \u6CE8\u610F\uFF1A\u4E0D\u8981\u8BBE\u7F6E color\uFF0C\u8BA9\u8BED\u6CD5\u9AD8\u4EAE\u4E3B\u9898\u63A7\u5236\u6587\u5B57\u989C\u8272 */\n#wemd pre code.hljs {\n    display: block;\n    padding: 16px;\n    background: #000;\n    /* \u7EAF\u9ED1 */\n    color: #CCFF00;\n    /* \u9ED8\u8BA4\u8367\u5149\u7EFF\u6587\u5B57 */\n    font-size: 13px;\n    line-height: 1.5;\n    border-radius: 0;\n    /* \u76F4\u89D2 */\n    font-family: \"Menlo\", \"Courier New\", monospace;\n    overflow-x: auto;\n    white-space: pre;\n  min-width: max-content;\n    border: 2px solid #000;\n    box-shadow: 6px 6px 0px #ddd;\n}\n\n/* \u4F18\u5316\u6DF1\u8272\u80CC\u666F\u4E0B\u7684\u8BED\u6CD5\u9AD8\u4EAE\u989C\u8272 - \u4F7F\u7528\u9AD8\u5BF9\u6BD4\u5EA6\u4EAE\u8272 */\n#wemd pre code.hljs .hljs-comment,\n#wemd pre code.hljs .hljs-quote {\n    color: #888;\n}\n\n#wemd pre code.hljs .hljs-keyword,\n#wemd pre code.hljs .hljs-selector-tag {\n    color: #FF6B9D;\n    font-weight: bold;\n}\n\n#wemd pre code.hljs .hljs-string,\n#wemd pre code.hljs .hljs-doctag {\n    color: #FFD93D;\n}\n\n#wemd pre code.hljs .hljs-number,\n#wemd pre code.hljs .hljs-literal {\n    color: #6BCF7F;\n}\n\n#wemd pre code.hljs .hljs-title,\n#wemd pre code.hljs .hljs-section {\n    color: #4D9DE0;\n    font-weight: bold;\n}\n\n#wemd pre code.hljs .hljs-built_in,\n#wemd pre code.hljs .hljs-builtin-name {\n    color: #E85D75;\n    font-weight: bold;\n}\n\n/* \u5982\u679C\u6CA1\u6709\u8BED\u6CD5\u9AD8\u4EAE\uFF0C\u8BBE\u7F6E\u9ED8\u8BA4\u8367\u5149\u7EFF */\n#wemd pre code:not(.hljs) {\n    color: #CCFF00;\n    background: #000;\n    border: 2px solid #000;\n    box-shadow: 6px 6px 0px #ddd;\n}\n\n/* \u8868\u683C - Excel \u7C97\u6846\u98CE\u683C */\n#wemd table {\n    width: 100%;\n    border-collapse: collapse;\n    margin: 40px 0;\n    font-size: 14px;\n    border: 2px solid #000;\n    box-shadow: 6px 6px 0px #000;\n}\n\n#wemd table tr th {\n    background: #6A00FF;\n    /* \u7D2B\u8272\u8868\u5934 */\n    color: #fff;\n    font-weight: 900;\n    border: 1px solid #000;\n    padding: 12px;\n    text-align: left;\n    text-transform: uppercase;\n}\n\n#wemd table tr td {\n    border: 1px solid #000;\n    padding: 12px;\n    color: #000;\n    background: #fff;\n}\n\n/* \u9694\u884C\u53D8\u8272 - \u9EC4\u8272 */\n#wemd table tr:nth-child(even) td {\n    background-color: #faffd1;\n}\n\n/* \u811A\u6CE8 */\n#wemd .footnote-word,\n#wemd .footnote-ref {\n    color: #6A00FF;\n    font-weight: bold;\n}\n\n#wemd .footnotes-sep {\n    border-top: 2px solid #000;\n    padding-top: 20px;\n    margin-top: 60px;\n    font-size: 14px;\n    font-weight: 900;\n    color: #000;\n    text-transform: uppercase;\n}\n\n#wemd .footnote-num {\n    font-weight: 900;\n    color: #fff;\n    background: #000;\n    padding: 1px 4px;\n    margin-right: 4px;\n    font-size: 12px;\n}\n\n#wemd .footnote-item p {\n    color: #333;\n    font-size: 12px;\n    margin: 4px 0;\n}\n\n/* \u516C\u5F0F */\n#wemd .block-equation > svg {\n    max-width: 100% !important;\n}\n\n#wemd .inline-equation > svg {\n    max-width: 100%;\n    vertical-align: middle;\n}\n\n/* \u63D0\u793A\u5757 - \u65B0\u7C97\u91CE\u4E3B\u4E49\u98CE\u683C */\n#wemd .callout {\n    margin: 40px 0;\n    padding: 20px;\n    background: #f4f4f4;\n    border: 2px solid #000;\n    box-shadow: 6px 6px 0px #6A00FF;\n    border-radius: 0;\n}\n\n#wemd .callout-title {\n    font-weight: 900;\n    margin-bottom: 10px;\n    text-transform: uppercase;\n    color: #000;\n    font-size: 16px;\n}\n\n#wemd .callout-icon { margin-right: 8px;\n    margin-right: 6px;\n}\n\n#wemd .callout-note { border-left: 8px solid #6A00FF; }\n#wemd .callout-tip { border-left: 8px solid #CCFF00; }\n#wemd .callout-important { border-left: 8px solid #6A00FF; }\n#wemd .callout-warning { border-left: 8px solid #CCFF00; }\n#wemd .callout-caution { border-left: 8px solid #FF6B9D; }\n\n/* Imageflow CSS */\n#wemd .imageflow-layer1 {\n  margin-top: 1em;\n  margin-bottom: 0.5em;\n  /* white-space: normal; */\n  border: 0px none;\n  padding: 0px;\n  overflow: hidden;\n}\n\n#wemd .imageflow-layer2 {\n  white-space: nowrap;\n  width: 100%;\n  overflow-x: scroll;\n}\n\n#wemd .imageflow-layer3 {\n  display: inline-block;\n  word-wrap: break-word;\n  white-space: normal;\n  vertical-align: top;\n  width: 80%;\n  margin-right: 10px;\n  flex-shrink: 0;\n}\n\n#wemd .imageflow-img {\n  display: block;\n  width: 100%;\n  height: auto;\n  max-height: 300px;\n  object-fit: contain;\n  border-radius: 4px;\n}\n\n#wemd .imageflow-caption {\n  text-align: center;\n  margin-top: 0px;\n  padding-top: 0px;\n  color: #888;\n}\n";
